<?php
namespace ProcessWire;

final class MercatoHeadlessApiException extends WireException {
    public function __construct(public readonly string $apiCode, string $message, public readonly int $httpStatus = 400, public readonly array $fields = []) { parent::__construct($message, $httpStatus); }
}

final class MercatoHeadlessApiService extends Wire {
    public function __construct(private readonly Mercato $commerce) { parent::__construct(); }

    public function maxBodyBytes(): int { return max(1024, min(1048576, (int) ($this->commerce->headless_api_max_body_bytes ?? 65536))); }
    public function requestHeaders(): array {
        $headers=[]; foreach ($_SERVER as $key=>$value) if (str_starts_with($key,'HTTP_')) $headers[strtolower(str_replace('_','-',substr($key,5)))] = (string) $value; return $headers;
    }
    public function isAllowedOrigin(string $origin): bool {
        if (!preg_match('#^https://[^/]+$#i', $origin)) return false;
        $allowed=preg_split('/[\r\n,]+/', (string) ($this->commerce->headless_api_allowed_origins ?? ''), -1, PREG_SPLIT_NO_EMPTY) ?: [];
        return in_array(strtolower($origin), array_map(static fn($v)=>strtolower(trim($v)), $allowed), true);
    }
    public function assertRequestAllowed(string $bucket): void {
        if (!empty($this->commerce->production) && !str_starts_with(strtolower($this->commerce->getHttpRoot()), 'https://')) throw new MercatoHeadlessApiException('https_required','Production API requires HTTPS.',503);
        $limit=max(1,min(1000,(int)($this->commerce->headless_api_rate_limit_per_minute??60))); $ip=(string)($this->wire('session')->getIP()?:'unknown'); $window=(int)floor(time()/60);
        $key='Mercato.api.rate.'.hash('sha256',$ip.'|'.$bucket.'|'.$window); $count=(int)$this->wire('cache')->get($key); if($count >= $limit) throw new MercatoHeadlessApiException('rate_limited','Too many API requests.',429);
        $this->wire('cache')->save($key,(string)($count+1),90);
    }

    public function dispatch(string $method,string $resource='',string $id='',string $action='',array $body=[],array $query=[],array $headers=[]): array {
        $resource=strtolower(trim($resource?:'store')); $action=strtolower(trim($action));
        if($method==='GET'&&$resource==='store') return ['resource'=>'store','data'=>$this->store()];
        if($method==='GET'&&$resource==='products'&&$id==='') return ['resource'=>'products']+$this->products($query);
        if($method==='GET'&&$resource==='products') return ['resource'=>'product','data'=>$this->product($id)];
        if($method==='GET'&&$resource==='collections'&&$id==='') return ['resource'=>'collections']+$this->collections($query);
        if($method==='GET'&&$resource==='collections') return ['resource'=>'collection','data'=>$this->collection($id,$query)];
        if($method==='POST'&&$resource==='quotes'&&$id==='') return ['status'=>200,'resource'=>'quote','data'=>$this->quote($body)];
        if($method==='POST'&&$resource==='checkouts'&&$id==='') return ['status'=>201,'resource'=>'checkout','data'=>$this->createCheckout($body,$this->requireIdempotency($headers))];
        if($method==='GET'&&$resource==='checkouts'&&$id!=='') return ['resource'=>'checkout','data'=>$this->checkout($id,$this->token($headers))];
        if($method==='POST'&&$resource==='checkouts'&&$id!==''&&$action==='complete') return ['resource'=>'checkout','data'=>$this->complete($id,$this->token($headers),$body,$this->requireIdempotency($headers))];
        if($method==='GET'&&$resource==='orders'&&$id!=='') return ['resource'=>'order','data'=>$this->order($id,$this->token($headers))];
        throw new MercatoHeadlessApiException('route_not_found','API route not found.',404);
    }

    public function store(): array {
        $policies=[]; foreach($this->commerce->getPolicyPages() as $page) $policies[]=['title'=>(string)($page->title?:$page->name),'url'=>(string)$page->httpUrl()];
        $payments=[]; foreach((array)($this->commerce->enabled_payment_methods??[]) as $method){ try{$gateway=$this->commerce->getGateway((string)$method);$status=$gateway->getSetupStatus();$payments[]=['id'=>(string)$method,'gateway'=>$gateway->getName(),'label'=>$gateway->getPaymentMethods()[$method]??$gateway->getLabel(),'ready'=>$status->ready,'capabilities'=>$gateway->getCapabilities()->toArray()];}catch(\Throwable){} }
        return $this->extend(['name'=>(string)($this->commerce->seo_site_name?:'Mercato Store'),'currency'=>MercatoCurrency::normalizeCode((string)$this->commerce->currency),'api_version'=>'v1','checkout_available'=>$this->commerce->operationalService()->isCheckoutAvailable(),'payments'=>$payments,'policies'=>$policies,'links'=>['products'=>'/api/mercato/v1/products','collections'=>'/api/mercato/v1/collections','quotes'=>'/api/mercato/v1/quotes','checkouts'=>'/api/mercato/v1/checkouts']], 'store');
    }
    public function products(array $query): array {
        $page=max(1,(int)($query['page']??1));$limit=max(1,min(50,(int)($query['limit']??20)));$start=($page-1)*$limit;$template=$this->safe((string)($this->commerce->product_template?:'mrc-product'));
        $parts=["template=$template",'mrc_product_status=active'];$q=trim((string)($query['q']??''));if($q!=='')$parts[]='title|mrc_sku|mrc_description%='.$this->safe($q);$type=trim((string)($query['type']??''));if($type!=='')$parts[]='mrc_product_type='.$this->safe($type);$collection=(int)($query['collection']??0);if($collection>0)$parts[]='mrc_collections='.$collection;
        $sort=match((string)($query['sort']??'title')){'price'=>'mrc_price','-price'=>'-mrc_price','-created'=>'-created',default=>'title'};$base=implode(', ',$parts);$total=(int)$this->wire('pages')->count($base);$items=[];foreach($this->wire('pages')->find("$base, sort=$sort, start=$start, limit=$limit") as $p)$items[]=$this->serializeProduct($p);
        return ['data'=>$items,'meta'=>$this->pagination($page,$limit,$total)];
    }
    public function product(string|int $id): array { $p=$this->findProduct($id);if(!$p)throw new MercatoHeadlessApiException('not_found','Product not found.',404);return $this->serializeProduct($p); }
    public function collections(array $query): array {
        $page=max(1,(int)($query['page']??1));$limit=max(1,min(50,(int)($query['limit']??20)));$start=($page-1)*$limit;$base='template=mrc-collection';$total=(int)$this->wire('pages')->count($base);$items=[];foreach($this->wire('pages')->find("$base, sort=sort, sort=title, start=$start, limit=$limit")as$p)$items[]=$this->serializeCollection($p);return ['data'=>$items,'meta'=>$this->pagination($page,$limit,$total)];
    }
    public function collection(string|int $id,array $query=[]): array { $p=$this->findPage('mrc-collection',$id);if(!$p)throw new MercatoHeadlessApiException('not_found','Collection not found.',404);$data=$this->serializeCollection($p);$query['collection']=$p->id;$data['products']=$this->products($query);return $data; }
    public function quote(array $body): array {
        $items=$this->requestedItems($body['items']??[]);$customer=is_array($body['customer']??null)?$body['customer']:[];$options=is_array($body['options']??null)?$body['options']:[];$quote=$this->commerce->getHeadlessCheckoutQuote($items,$customer,$options);
        if(!empty($options['discount_code'])&&empty($quote['discount_valid']))throw new MercatoHeadlessApiException('validation_failed','Coupon could not be applied.',422,['discount_code'=>'Coupon is invalid or unavailable.']);
        return $this->publicQuote($quote);
    }
    public function createCheckout(array $body,string $idempotency): array {
        $requestHash=hash('sha256',$this->canonical($body));$cacheKey=$this->idemKey('create',$idempotency);$cached=$this->cached($cacheKey,$requestHash);if($cached!==null)return $cached;
        $items=$this->requestedItems($body['items']??[]);$customer=is_array($body['customer']??null)?$body['customer']:[];$options=is_array($body['options']??null)?$body['options']:[];$fields=$this->validateCheckoutInput($customer,$options);if($fields)throw new MercatoHeadlessApiException('validation_failed','Checkout data is invalid.',422,$fields);
        $quote=$this->commerce->getHeadlessCheckoutQuote($items,$customer,$options);if(!empty($options['discount_code'])&&empty($quote['discount_valid']))throw new MercatoHeadlessApiException('validation_failed','Coupon could not be applied.',422,['discount_code'=>'Coupon is invalid or unavailable.']);
        $session=$this->wire('session');$sessionKeys=['mrc_cart_items','mrc_cart_updated_at','mrc_discount_code','mrc_pending_order','mrc_checkout_started_nonce','mrc_checkout_redirect'];$snapshot=[];foreach($sessionKeys as$key)$snapshot[$key]=$session->get($key);$originalCart=$this->commerce->cart()->toArray();
        try{
