            $order=$this->commerce->getOrder((int)$pending['mrc_order_page_id']);if(!$order)throw new WireException('Pending order was not found.',502);$token=$this->idempotentToken($cacheKey,$requestHash);$checkoutId=$this->opaque('chk',18);$orderId=$this->opaque('ord',18);$expires=time()+max(5,min(10080,(int)($this->commerce->headless_api_token_ttl_minutes??60)))*60;
