    private function serializeCheckout(Page $o):array{return ['id'=>(string)$o->mrc_api_checkout_id,'payment_status'=>(string)$o->mrc_payment_status,'payment_complete'=>(int)$o->mrc_payment_complete===1,'order_status'=>$this->commerce->getDerivedOrderStatus($o),'reservation_expires_at'=>(string)$o->mrc_inventory_reserved_until,'total'=>round((float)$o->mrc_total_amount,2),'currency'=>(string)$o->mrc_currency,'updated_at'=>gmdate(DATE_ATOM,(int)$o->modified)];}
