    private function publicQuote(array $q):array{return array_intersect_key($q,array_flip(['items','item_count','currency','subtotal','shipping','discount','tax','total','discount_code','discount_valid','fulfilment_method','fulfilment_label','fulfilment_methods','requires_payment']));}
